const UNITS = ['B', 'KB', 'MB', 'GB'];

export function formatBytes(n) {
  if (typeof n !== 'number' || Number.isNaN(n)) {
    throw new TypeError('formatBytes expects a number');
  }
  if (n < 0) throw new RangeError('formatBytes expects a non-negative number');
  if (!Number.isFinite(n)) throw new RangeError('formatBytes expects a finite number');

  if (n < 1024) return `${Math.round(n)} B`;

  let i = 0;
  let value = n;
  while (value >= 1024 && i < UNITS.length - 1) {
    value /= 1024;
    i++;
  }
  // Rounding can push a value to 1024.0 (e.g. 1023.96 KB); move up a unit.
  if (Number(value.toFixed(1)) >= 1024 && i < UNITS.length - 1) {
    value /= 1024;
    i++;
  }
  return `${value.toFixed(1)} ${UNITS[i]}`;
}"}

{"path": "test/format.test.js", "content": "import { test } from 'node:test';
import assert from 'node:assert/strict';
import { pad, formatBytes } from '../src/format.js';

test('pad', () => assert.equal(pad(3), '03'));

test('formatBytes: bytes have no decimals', () => {
  assert.equal(formatBytes(0), '0 B');
  assert.equal(formatBytes(512), '512 B');
  assert.equal(formatBytes(1023), '1023 B');
});

test('formatBytes: larger units use one decimal, base 1024', () => {
  assert.equal(formatBytes(1024), '1.0 KB');
  assert.equal(formatBytes(1536), '1.5 KB');
  assert.equal(formatBytes(1024 ** 2), '1.0 MB');
  assert.equal(formatBytes(1.5 * 1024 **3), '1.5 GB');
  assert.equal(formatBytes(2048 * 1024 **3), '2048.0 GB');
});

test('formatBytes: rounding up moves to the next unit', () => {
  assert.equal(formatBytes(1024 ** 2 - 1), '1.0 MB');
});

test('formatBytes: negative numbers throw RangeError', () => {
  assert.throws(() => formatBytes(-1), RangeError);
});
"}
